92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        this.clinicService.saveOwner(owner);
110	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
111	        headers.setLocation(UriComponentsBuilder.newInstance()
112	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
113	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
114	    }
115	
116	    /**
117	     * Determines whether an owner already exists that uses the same telephone number
118	     * as the given one. Telephone numbers must be unique across all owners. The
119	     * comparison ignores letter case and any surrounding or repeated whitespace.
120	     */
121	    private boolean isDuplicateOwner(Owner owner) {
122	        String telephone = normalize(owner.getTelephone());
123	        return this.clinicService.findAllOwners().stream()
124	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
125	    }
126	
127	    /**
128	     * Determines whether another owner already uses the same email address as the given one.
129	     * Email addresses, when supplied, must be unique across all owners. An owner without an
130	     * email address is never considered a duplicate. The comparison ignores letter case and
131	     * any surrounding or repeated whitespace.
132	     */
133	    private boolean isDuplicateEmail(Owner owner) {
134	        String email = normalize(owner.getEmail());
135	        if (email == null || email.isEmpty()) {
136	            return false;
137	        }
138	        return this.clinicService.findAllOwners().stream()
139	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
140	    }
141	
142	    /**
143	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
144	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
145	     * and "John Smith" normalize to the same key and so count as the same person.
146	     */
147	    private static String normalize(String value) {
148	        if (value == null) {
149	            return null;
150	        }
151	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
152	    }
