159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        currentOwner.setAddress(ownerFieldsDto.getAddress());
162	        currentOwner.setCity(ownerFieldsDto.getCity());
163	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
164	        currentOwner.setLastName(ownerFieldsDto.getLastName());
165	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
166	        this.clinicService.saveOwner(currentOwner);
167	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
168	    }
